using Microsoft.EntityFrameworkCore;

namespace UltimaExodus.Data.Persistence;

public class UltimaExodusDbContext : DbContext
{
    public UltimaExodusDbContext(DbContextOptions<UltimaExodusDbContext> options)
        : base(options)
    {
    }

    public DbSet<GameState> GameStates => Set<GameState>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Single-player, single save: the row's Id is always set by us (always 1),
        // never auto-generated by the database.
        modelBuilder.Entity<GameState>()
            .Property(g => g.Id)
            .ValueGeneratedNever();
    }
}